def count_calls(func):
    def wrapper(*args, **kwargs):
        wrapper.calls += 1
        return func(*args, **kwargs)

    wrapper.calls = 0
    return wrapper


@count_calls
def greet(name):
    return "Hello, " + name


@count_calls
def shout(name):
    return name.upper() + "!"


print(greet("Asha"))
print(shout("ravi"))
print(greet.calls + shout.calls)
